# 낱말을 글자 수별로 묶어서 한 줄씩 보여줘요.
words = input().split()
groups = {}
for w in words:
    # 글자 수를 키로 삼아 같은 키의 낱말을 리스트에 모아요.
    groups.setdefault(len(w), []).append(w)
for length in sorted(groups):
    print(f"{length}글자:", " ".join(groups[length]))
